using System.Security.Claims; using Microsoft.EntityFrameworkCore; using PersonalUltra.Infrastructure;
namespace PersonalUltra.StudentApi.Endpoints;
public static class BrandingEndpointExtensions { public static void MapBrandingApi(this WebApplication app){app.MapGet("/api/v1/branding",async(PersonalUltraDbContext db,ClaimsPrincipal u,CancellationToken ct)=>{if(!Guid.TryParse(u.FindFirstValue(ClaimTypes.NameIdentifier),out var id)||u.FindFirstValue("subject")!="student")return ApiEndpointExtensions.ApiError("STUDENT_SESSION_REQUIRED","Use uma sessão válida.",403);var b=await db.TrainerStudents.AsNoTracking().Where(x=>x.StudentId==id&&x.EndedAt==null).Select(x=>x.Trainer.Branding).SingleOrDefaultAsync(ct);return Results.Ok(b is null?null:new {b.DisplayName,PrimaryColor=b.PrimaryColor??"#FF6A13",b.LogoUrl});}).RequireAuthorization();} }
